local StateSpearMaker = {}
local PRODUCTS = {
    simple_iron_state_spear = { name = "Preprost železni državni kopje", ironCost = 2, woodCost = 2, time = 5, cost = 150, prestige = 5, happiness = 2, description = "Preprost železni državni kopje za parade." },
    silver_head_state_spear = { name = "Srebrnoglavi državni kopje", silverCost = 2, ironCost = 1, woodCost = 2, time = 8, cost = 380, prestige = 12, happiness = 3, description = "Srebrnoglavi državni kopje za trgovce." },
    gold_trimmed_state_spear = { name = "Zlatookrasni državni kopje", goldCost = 1, silverCost = 1, ironCost = 1, woodCost = 2, time = 12, cost = 900, prestige = 22, happiness = 4, description = "Zlatookrasni državni kopje za plemiče." },
    jewel_set_state_spear = { name = "Draguljasta državni kopje", goldCost = 2, silverCost = 1, ironCost = 1, woodCost = 2, jewelCost = 1, time = 16, cost = 2000, prestige = 35, happiness = 6, description = "Državni kopje z draguljem za visoke plemiče." },
    pearl_set_state_spear = { name = "Bisernavi državni kopje", goldCost = 2, silverCost = 1, ironCost = 1, woodCost = 2, jewelCost = 1, pearlCost = 1, time = 20, cost = 4200, prestige = 50, happiness = 8, description = "Državni kopje z biseri za visoko plemstvo." },
    royal_grand_state_spear = { name = "Kraljevski veliki državni kopje", goldCost = 3, silverCost = 2, ironCost = 1, woodCost = 2, jewelCost = 2, pearlCost = 2, time = 27, cost = 9000, prestige = 72, happiness = 13, description = "Veliki kraljevski državni kopje z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    state_spear_workshop = { name = "Državno kopje delavnica", cost = { gold = 300, wood = 140, stone = 120, iron = 6 }, upkeep = 7, qualityBonus = 5 },
    armorer_loft = { name = "Okleparska podstrešje", cost = { gold = 1100, wood = 280, stone = 280, silver = 6, gold = 4 }, upkeep = 26, qualityBonus = 18 },
    master_spear_atelier = { name = "Mojstrski kopjarski atelje", cost = { gold = 2800, wood = 380, stone = 520, silver = 32, gold = 6 }, upkeep = 65, qualityBonus = 30 },
    royal_armory_palace = { name = "Kraljevska orožarnaica palača", cost = { gold = 12000, wood = 600, stone = 800, gold = 80, jewel = 18 }, upkeep = 240, qualityBonus = 55, prestigeBonus = 50 },
}
StateSpearMaker.ironStock = 14; StateSpearMaker.woodStock = 14; StateSpearMaker.silverStock = 8; StateSpearMaker.goldStock = 6; StateSpearMaker.jewelStock = 4; StateSpearMaker.pearlStock = 4
StateSpearMaker.productStock = {}; StateSpearMaker.buildings = {}; StateSpearMaker.maker = nil; StateSpearMaker.activeMaking = {}; StateSpearMaker.totalProducts = 0; StateSpearMaker.dayTimer = 0
function StateSpearMaker.init() StateSpearMaker.ironStock=14; StateSpearMaker.woodStock=14; StateSpearMaker.silverStock=8; StateSpearMaker.goldStock=6; StateSpearMaker.jewelStock=4; StateSpearMaker.pearlStock=4; StateSpearMaker.productStock={}; StateSpearMaker.buildings={}; StateSpearMaker.maker=nil; StateSpearMaker.activeMaking={}; StateSpearMaker.totalProducts=0; StateSpearMaker.dayTimer=0; print("[StateSpearMaker] Royal State Spear Maker System initialized (6 products, 4 buildings)") end
function StateSpearMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; StateSpearMaker.maker={name=n or ("Državni kopjar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Državni kopjar najet: %s (spretnost: %d)",StateSpearMaker.maker.name,s),"success") end; return true end
function StateSpearMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function StateSpearMaker.build(id) local ok,e=StateSpearMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(StateSpearMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function StateSpearMaker.getQualityBonus() local b=0; for _,bd in ipairs(StateSpearMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function StateSpearMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and StateSpearMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.woodCost and StateSpearMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.silverCost and StateSpearMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and StateSpearMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and StateSpearMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and StateSpearMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #StateSpearMaker.buildings==0 then return false,"Potrebna državno kopje delavnica" end; if not StateSpearMaker.maker then return false,"Potreben državni kopjar" end; return true end
function StateSpearMaker.make(pt,qty) qty=qty or 1; local ok,e=StateSpearMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then StateSpearMaker.ironStock=StateSpearMaker.ironStock-d.ironCost*qty end; if d.woodCost then StateSpearMaker.woodStock=StateSpearMaker.woodStock-d.woodCost*qty end; if d.silverCost then StateSpearMaker.silverStock=StateSpearMaker.silverStock-d.silverCost*qty end; if d.goldCost then StateSpearMaker.goldStock=StateSpearMaker.goldStock-d.goldCost*qty end; if d.jewelCost then StateSpearMaker.jewelStock=StateSpearMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then StateSpearMaker.pearlStock=StateSpearMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if StateSpearMaker.maker then t=math.max(1,t-math.floor(StateSpearMaker.maker.skill/12)) end; table.insert(StateSpearMaker.activeMaking,{id="statespear_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kovanje: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function StateSpearMaker.completeMaking(m) local q=1.0+(StateSpearMaker.getQualityBonus()/100); if StateSpearMaker.maker then q=q+(StateSpearMaker.maker.skill/140) end; q=math.min(2.5,q); StateSpearMaker.productStock[m.productType]=(StateSpearMaker.productStock[m.productType] or 0)+m.quantity; StateSpearMaker.totalProducts=StateSpearMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if StateSpearMaker.maker then StateSpearMaker.maker.itemsMade=StateSpearMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then StateSpearMaker.maker.skill=math.min(100,StateSpearMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Državni kopje izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"statespear.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function StateSpearMaker.update(dt) if not _G.state then return end; StateSpearMaker.dayTimer=StateSpearMaker.dayTimer+dt; if StateSpearMaker.dayTimer>=30 then StateSpearMaker.dayTimer=0; for i=#StateSpearMaker.activeMaking,1,-1 do local m=StateSpearMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then StateSpearMaker.completeMaking(m); table.remove(StateSpearMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(StateSpearMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if StateSpearMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function StateSpearMaker.getStats() return {ironStock=StateSpearMaker.ironStock,woodStock=StateSpearMaker.woodStock,silverStock=StateSpearMaker.silverStock,goldStock=StateSpearMaker.goldStock,jewelStock=StateSpearMaker.jewelStock,pearlStock=StateSpearMaker.pearlStock,productStock=StateSpearMaker.productStock,numBuildings=#StateSpearMaker.buildings,hasMaker=StateSpearMaker.maker~=nil,makerName=StateSpearMaker.maker and StateSpearMaker.maker.name or "—",makerSkill=StateSpearMaker.maker and StateSpearMaker.maker.skill or 0,activeMaking=#StateSpearMaker.activeMaking,totalProducts=StateSpearMaker.totalProducts} end
return StateSpearMaker
